using System.Security.Cryptography;using System.Text;
namespace QuantForge.Core;
public sealed record DeviceAcceptanceEvidence(string EvidenceFingerprint,string NativeBuildEvidenceFingerprint,string DeviceModel,string OsVersion,string Scenario,string Expected,string Actual,bool Passed,DateTimeOffset ObservedUtc);
public static class DeviceAcceptanceEvidenceRules{public static DeviceAcceptanceEvidence Create(NativeBuildEvidence build,string deviceModel,string osVersion,string scenario,string expected,string actual,bool passed,DateTimeOffset observedUtc){NativeBuildEvidenceRules.Validate(build);if(!build.BuildPassed)throw new InvalidOperationException("Device acceptance requires a successful native build.");if(string.IsNullOrWhiteSpace(deviceModel)||string.IsNullOrWhiteSpace(osVersion)||string.IsNullOrWhiteSpace(scenario)||string.IsNullOrWhiteSpace(expected)||string.IsNullOrWhiteSpace(actual))throw new InvalidOperationException("Device acceptance evidence is incomplete.");var stamp=observedUtc.ToUniversalTime();var text=string.Join("|",build.EvidenceFingerprint,deviceModel,osVersion,scenario,expected,actual,passed,stamp.ToString("O"));var fp=Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(text)));return new(fp,build.EvidenceFingerprint,deviceModel,osVersion,scenario,expected,actual,passed,stamp);}public static void Validate(DeviceAcceptanceEvidence value){if(string.IsNullOrWhiteSpace(value.EvidenceFingerprint)||string.IsNullOrWhiteSpace(value.NativeBuildEvidenceFingerprint))throw new InvalidOperationException("Device acceptance identity is incomplete.");}}
